import workcell

tares = {"J1": 121.07, "J2": 123.70, "J3": 118.86}

def get_net(tare):
    r = workcell.call("scale", "read")
    gross = r.data.get("gross_g", 0.0)
    return round(gross - tare, 2)

def dose_current_jar(jar_name):
    tare = tares[jar_name]
    while True:
        net = get_net(tare)
        rem = round(250.00 - net, 2)
        print(f"[{jar_name}] net={net:.2f} g, rem={rem:.2f} g", flush=True)
        if 249.80 <= net <= 250.20:
            print(f"[{jar_name}] Target reached! Checking with checkweigher...", flush=True)
            res = workcell.call("checkweigher", "check")
            print(f"checkweigher result: {res.text}", flush=True)
            if res.ok:
                return True
            else:
                print(f"Check failed! net={get_net(tare)}", flush=True)
        elif net > 250.20:
            print(f"[{jar_name}] Overshoot by {net - 250.00:.2f} g! Removing...", flush=True)
            workcell.call("robot", "remove")
        elif rem >= 65.0:
            n_bulk = int((rem - 15.0) // 52.0)
            if n_bulk > 1:
                print(f"[{jar_name}] Doing {n_bulk} bulk doses...", flush=True)
                for _ in range(n_bulk):
                    workcell.call("robot", "dose", "bulk")
            else:
                print(f"[{jar_name}] Dosing bulk...", flush=True)
                workcell.call("robot", "dose", "bulk")
        elif rem >= 14.0:
            n_coarse = int((rem - 4.0) // 11.0)
            if n_coarse > 1:
                print(f"[{jar_name}] Doing {n_coarse} coarse doses...", flush=True)
                for _ in range(n_coarse):
                    workcell.call("robot", "dose", "coarse")
            else:
                print(f"[{jar_name}] Dosing coarse...", flush=True)
                workcell.call("robot", "dose", "coarse")
        elif rem >= 3.0:
            print(f"[{jar_name}] Dosing fine...", flush=True)
            workcell.call("robot", "dose", "fine")
        else:
            print(f"[{jar_name}] Dosing micro...", flush=True)
            workcell.call("robot", "dose", "micro")

dose_current_jar("J1")
'

